function callMethod(methodName, ...args) {
  if (window.go?.main?.App?.[methodName]) {
    return window.go.main.App[methodName](...args)
  }
  if (window.wails?.Call?.ByName) {
    return window.wails.Call.ByName(`main.App.${methodName}`, ...args)
  }
  console.debug(`[WailsBridge] 调用 main.App.${methodName} (独立运行/未连接原生环境)`)
  return Promise.resolve(null)
}

export function ClearCacheDirectory(arg1) {
  return callMethod('ClearCacheDirectory', arg1)
}

